2 files changed, +33 -2.

```diff
diff --git a/src/todo.ts b/src/todo.ts
index 868400f..bfaea80 100644
--- a/src/todo.ts
+++ b/src/todo.ts
@@ -13,10 +13,20 @@ export interface Summary {
   overdue: number;
 }

-/** Adds a todo and returns a new list. Ids grow by one from the highest existing id. */
+const MAX_TITLE_LENGTH = 100;
+
+/**
+ * Adds a todo and returns a new list. Ids grow by one from the highest existing id.
+ * The title is trimmed; an empty or over-100-character title throws an Error.
+ */
 export function addTodo(todos: readonly Todo[], title: string, dueAt?: number): Todo[] {
+  const trimmed = title.trim();
+  if (trimmed.length === 0) throw new Error("Title must not be empty");
+  if (trimmed.length > MAX_TITLE_LENGTH) {
+    throw new Error(`Title must be at most ${MAX_TITLE_LENGTH} characters`);
+  }
   const id = todos.reduce((max, t) => Math.max(max, t.id), 0) + 1;
-  const todo: Todo = { id, title, done: false };
+  const todo: Todo = { id, title: trimmed, done: false };
   if (dueAt !== undefined) todo.dueAt = dueAt;
   return [...todos, todo];
 }
diff --git a/test/todo.test.ts b/test/todo.test.ts
index d71db47..21f9437 100644
--- a/test/todo.test.ts
+++ b/test/todo.test.ts
@@ -14,6 +14,27 @@ describe("addTodo", () => {
     expect(before).toHaveLength(1);
   });

+  it("trims the title", () => {
+    expect(addTodo([], "  hello  ")[0]?.title).toBe("hello");
+  });
+
+  it("rejects an empty title", () => {
+    expect(() => addTodo([], "")).toThrow();
+  });
+
+  it("rejects a whitespace-only title", () => {
+    expect(() => addTodo([], "   \t ")).toThrow();
+  });
+
+  it("accepts a title of exactly 100 characters", () => {
+    const title = "a".repeat(100);
+    expect(addTodo([], title)[0]?.title).toBe(title);
+  });
+
+  it("rejects a title of 101 characters", () => {
+    expect(() => addTodo([], "a".repeat(101))).toThrow();
+  });
+
   it("keeps the due time", () => {
     expect(addTodo([], "a", 100)[0]?.dueAt).toBe(100);
   });
```

